<?php

namespace App\Repository;

use App\Entity\City;
use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;
use Doctrine\Persistence\ManagerRegistry;
use http\QueryString;
use Symfony\Contracts\Translation\TranslatorInterface;

/**
 * CityRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class CityRepository extends ServiceEntityRepository implements ChildColumTemplateRepository
{
    private TranslatorInterface $translator;

    public function __construct(ManagerRegistry $registry, TranslatorInterface $translator) {
		parent::__construct($registry, City::class);
		$this->translator = $translator;
	}

    public function getByRegionId(int $regionId): array {
        return array_map(
            function (City $city): array {
                return [
                    'id' => $city->getId(),
                    'name' => $this->translator->trans($city->getName()),
                ];
            },
            $this->createQueryBuilder('c')
                ->where('c.region = :region')
                ->setParameter('region', $regionId)
                ->getQuery()
                ->getResult()
        );
    }

	/**
	 * @param int $countryId
	 * @return string[]
	 */
	function getNamesByCountry(int $countryId): array {
		return $this->createQueryBuilder('city')
			->select('city.name')
			->join('city.region', 'region')
			->join('region.country', 'country')
			->where('region.country = :countryId')
			->setParameter('countryId',$countryId)
			->getQuery()
			->getSingleColumnResult();
	}

	/**
	 * @param int $regionId
	 * @return string[]
	 */
	function getNamesByRegion(int $regionId): array {
        return array_map(
            function (string $name): string {
                return $this->translator->trans($name);
            },
            $this->createQueryBuilder('city')
                ->select('city.name')
                ->where('city.region = :regionId')
                ->setParameter('regionId', $regionId)
                ->getQuery()
                ->getSingleColumnResult()
        );
	}

	/**
	 * @param int $id
	 * @return string[]
	 */
	public function getNameByParentId(int $id): array {
		return $this->getNamesByRegion($id);
	}
}
